mapper.select:
SELECT vrfc_sn AS ruleId, levl_seq AS level, vrfc_tbl_nm AS srcTable, vrfc_col_nm AS field, vrfc_rul_nm AS rule, rfrnc_nm AS ref, rfrnc_dtl_nm AS refDetail, CASE WHEN esntl_yn = 'Y' THEN true ELSE false END AS required FROM kids_own.tb_cm_m_vrfc WHERE std_se_cd = '04' AND lower(trim(vrfc_tbl_nm)) = lower(trim(#{table})) AND vrfc_rul_nm = #{rule}
AND esntl_yn = 'Y' AND esntl_yn = 'N'
ORDER BY vrfc_sn
